import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-22（材料 / 高分子 / 生物催化）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-22-materials.md","filePath":"topics/materials/science-daily-2026-10-22-materials.md"}'),e={name:"topics/materials/science-daily-2026-10-22-materials.md"};function g(i,o,a,l,c,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-22-材料-高分子-生物催化" tabindex="-1">科学日报 · 2026-10-22（材料 / 高分子 / 生物催化） <a class="header-anchor" href="#科学日报-·-2026-10-22-材料-高分子-生物催化" aria-label="Permalink to &quot;科学日报 · 2026-10-22（材料 / 高分子 / 生物催化）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> — 第41期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-materials</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-22-把酶「热嵌」进塑料——让可堆肥塑料在深海真正降解" tabindex="-1">科学日报 2026-10-22：把酶「热嵌」进塑料——让可堆肥塑料在深海真正降解 <a class="header-anchor" href="#科学日报-2026-10-22-把酶「热嵌」进塑料——让可堆肥塑料在深海真正降解" aria-label="Permalink to &quot;科学日报 2026-10-22：把酶「热嵌」进塑料——让可堆肥塑料在深海真正降解&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ DOI: 10.1038/s41586-026-11192-1</p></blockquote><ul><li>问题：<strong>持久性塑料在海洋中累积</strong>造成广泛环境问题。商用<strong>可堆肥塑料</strong>在工业堆肥条件下降解良好，但在<strong>海洋、尤其深海</strong>中降解<strong>非常有限</strong>。</li><li>方法：把**酶热嵌入（thermally embedding）**可堆肥聚酯 —— <strong>PBS、PBSA、PCL、PBAT</strong> 四种。</li><li>结果（跨深度验证）： <ul><li><strong>757 m 深海</strong>：5 个月内<strong>接近完全降解</strong>。</li><li><strong>5,503 m</strong> 深海海底极端条件下：仍观察到<strong>中等程度</strong>生物降解。</li><li><strong>近岸海水</strong>：仅 <strong>0.1 wt%</strong> 的痕量酶即可让薄膜<strong>快速降解</strong>。</li><li><strong>力学性能</strong>与不含酶的聚酯相当（→ 不牺牲使用性能）。</li><li>化学分析确认生成<strong>低分子量降解产物</strong>，<strong>BOD（生化需氧量）<strong>测量支持</strong>矿化</strong>。</li></ul></li><li>结论：<strong>降解能力可以被「预制」进材料本体</strong>，而不必依赖环境里恰好存在合适的微生物群落；且这个策略<strong>在 2–6 m 到 5,503 m 的整个深度谱上都成立</strong>。</li><li>洞察（对本库 <code>materials</code>）：这条属于「<strong>把功能从环境依赖改成材料自带</strong>」的一类设计动作。库内 10-09「把缺陷当强化特征」、10-21「螺旋位错当组织指令」都是在<strong>材料内部预置一个&quot;程序&quot;</strong>；而本条预置的是一段<strong>催化程序</strong>（酶）。值得注意的是<strong>剂量极低（0.1 wt%）就能改变全局行为</strong> —— 这与本库重复出现的「<strong>少量定向元件 &gt; 大量均质堆料</strong>」同构（对照 10-21 晨报：抑制性少数 vs 冗余多数）。</li></ul><hr><h2 id="科学日报-2026-10-22-从头设计「人工金属酶」光催化剂——给廉价金属配合物装上对映选择性" tabindex="-1">科学日报 2026-10-22：从头设计「人工金属酶」光催化剂——给廉价金属配合物装上对映选择性 <a class="header-anchor" href="#科学日报-2026-10-22-从头设计「人工金属酶」光催化剂——给廉价金属配合物装上对映选择性" aria-label="Permalink to &quot;科学日报 2026-10-22：从头设计「人工金属酶」光催化剂——给廉价金属配合物装上对映选择性&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ DOI: 10.1038/s41586-026-11317-6</p></blockquote><ul><li>问题：<strong>人工金属酶（ArMs）<strong>把合成金属辅因子与蛋白骨架结合，有望让</strong>简单易得的金属催化剂</strong>获得<strong>对映选择性</strong>；但<strong>骨架发现</strong>长期受限于<strong>试错法</strong>与<strong>天然蛋白的功能边界</strong>。对<strong>金属多吡啶光催化剂</strong>尤其尖锐：它们广泛用于<strong>可见光化学</strong>，却难以在蛋白骨架内实现<strong>高对映选择性光催化</strong>。</li><li>方法（两段式）：① <strong>生成式蛋白质设计</strong> —— <strong>从头（de novo）<strong>造出能</strong>选择性结合</strong>这类光催化剂的骨架；② <strong>定向进化</strong> —— 把所得 ArMs 改造成<strong>高效、高对映选择性</strong>的光催化剂。</li><li>结果： <ul><li>支持<strong>多种光驱动反应</strong>、<strong>高催化周转</strong>、<strong>催化剂可回收</strong>。</li><li>可直接使用<strong>市售外消旋金属配合物</strong>（不必先做手性拆分）→ 工程上很实用。</li><li><strong>机制（光谱证据）</strong>：蛋白环境<strong>延长了光催化剂激发态寿命</strong>，并把<strong>底物组织在辅因子附近</strong> → 改变<strong>能量转移</strong>并控制<strong>立体选择性</strong>。</li></ul></li><li>结论：<strong>「天然蛋白没有的伙伴」也可以被设计出来</strong> —— 生成式设计解决「<strong>结合</strong>」，定向进化解决「<strong>选择性与效率</strong>」。</li><li>洞察（对本库 <code>materials</code> × <code>ai-system-architecture</code>）：这是「<strong>生成式设计 + 进化式精修</strong>」的两段式范式的又一实证（库内 10-13 Prompteina 用自然语言设计全原子蛋白、06-27 Prompteina 找到 107 nM 结合体）。<strong>要点是分工</strong>：生成模型擅长<strong>枚举可用的结构空间</strong>，但<strong>精细指标（对映选择性）仍靠实验反馈的迭代搜索</strong>。对本库迁移：<strong>「生成负责提出候选，验证负责收敛精度」</strong> —— 与晨报反复点名的「<strong>机制与数字分账</strong>」是同一算法的不同侧面。另注：蛋白骨架在此扮演的角色不是&quot;催化剂&quot;，而是**「组织微环境的外壳」**（延长激发态、摆好底物）—— <strong>功能来自把东西摆对位置，而不是来自新成分</strong>（同 10-21「几何即功能」）。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第41期 科学板块</p></blockquote><p>关键词：酶嵌入聚酯、enzyme-embedded polyester、PBS、PBSA、PCL、PBAT、深海降解、5503m、757m、0.1wt%痕量酶、矿化、BOD、可堆肥塑料、功能预置进材料、低剂量定向元件；人工金属酶、artificial metalloenzyme、ArMs、金属多吡啶光催化剂、可见光化学、对映选择性、生成式蛋白质设计、从头设计、de novo、定向进化、激发态寿命、能量转移、立体选择性、外消旋配合物、生成负责候选验证负责精度、几何即功能</p><p>关联：<code>topics/materials/science-daily-2026-10-21-materials.md</code>（螺旋位错超螺旋 + WSe₂/WS₂ 手性自旋模式）、<code>topics/materials/2026-q3-breakthroughs.md</code>、<code>topics/materials/index.md</code></p>',14)])])}const p=t(e,[["render",g]]);export{u as __pageData,p as default};
